function UN(x, i) { return CBP([x[0] + "<br>الصِّيغَةُ:", SGT[x[1]], "· الفِعْلُ:", x[2], "· المُتَعَجَّبُ مِنْهُ:", x[3]], i, x[4], x[5]); }
// İki sîga: [cümle, [birinci ×3], [ikinci ×3], Türkçe, açıklama]
function IS(x, i) { return CBP([x[0] + "<br>الأُولَى:", x[1], "<br>الثَّانِيَةُ:", x[2]], i, x[3], x[4]); }
// Sarîh + müevvel: [cümle, [sarîh ×3], [müevvel ×3], Türkçe, açıklama]
function SM(x, i) { return CBP([x[0] + "<br>بِمَصْدَرٍ صَرِيحٍ:", x[1], "<br>بِمَصْدَرٍ مُؤَوَّلٍ:", x[2]], i, x[3], x[4]); }
// لِلَّهِ دَرُّ: [cümle, [1 ×3], [2 ×3], [3 ×3], Türkçe, açıklama]
function DR(x, i) { return CBP([x[0] + "<br>١:", x[1], "<br>٢:", x[2], "<br>٣:", x[3]], i, x[4], x[5]); }

